package pzvrphysicality;
import java.util.*;import local.pzvr.*;
/** Real helper against authored native ownership providers; never upstream methods. */
public final class NativeInputOwnershipTest {
 private static int checks;private static void check(boolean value,String why){if(!value)throw new AssertionError(why);checks++;}
 private static void frame(boolean focused,int left,int right){var pose=new Math3.Pose(new Math3.Vec(0,0,0),new Math3.Quat(0,0,0,1));Engine.latestInput=new XrBackend.Frame(System.nanoTime(),true,focused,pose,List.of(),new XrBackend.Hand(pose,pose,true,0,0,left),new XrBackend.Hand(pose,pose,true,0,0,right));}
 private static void reset(){NativeInputOwnership.resetForTest();PhysicalBandaging.blocked=PhysicalBandaging.fail=false;PhysicalBandaging.calls=VrApi.calls=0;PhysicalBandaging.forbidden=null;Arrays.fill(VrApi.grabbed,false);Arrays.fill(VrApi.consumed,false);Engine.settings=new Settings();frame(true,0,0);}
 public static void main(String[] args)throws Exception {
  reset();var first=NativeInputOwnership.read();check(first.allows(0)&&first.allows(1)&&!first.globalBlocked(),"unclaimed fresh physical hands independently eligible");check(!first.allows(-1)&&!first.allows(2),"invalid physical side fails closed");check(first.generation(0)>0&&first.generation(2)==-1,"per-side lineage is detached and bounded");
  for(String aim:new String[]{"right","left"})for(boolean mirror:new boolean[]{false,true}){Engine.settings.dominantHand=aim;Engine.settings.mirrorControllerBindings=mirror;check(NativeInputOwnership.bindingHandIndex()==(mirror?0:1),"native binding slot uses mirror independently of aim "+aim+"/"+mirror);check(GripRoute.side("dominant.grip",NativeInputOwnership.bindingHandIndex())==(mirror?0:1),"grip route uses native logical slot");check(ConsumeRoute.resolve(true,false,NativeInputOwnership.bindingHandIndex(),mirror?"dominant.trigger":"other.trigger","native").equals("none"),"left physical consumption maps through binding mirror");}
  Engine.settings=null;check(NativeInputOwnership.bindingHandIndex()==-1,"unknown settings preserve native route with unavailable resolver");Engine.settings=new Settings();
  VrApi.grabbed[0]=true;var claimed=NativeInputOwnership.read();check(!claimed.allows(0)&&claimed.allows(1),"left native grab does not block unclaimed right hand");check(claimed.generation(0)!=first.generation(0)&&claimed.generation(1)==first.generation(1),"claim advances only affected physical lineage");check(!first.allows(0),"old detached snapshot cannot bypass later native claim");VrApi.grabbed[0]=false;check(!NativeInputOwnership.read().allows(0),"same raw frame cannot rearm after native release");frame(true,XrBackend.GRIP,0);check(!NativeInputOwnership.read().allows(0),"held raw grip cannot replay after claim clears");frame(true,XrBackend.TRIGGER,0);check(!NativeInputOwnership.read().allows(0),"held raw trigger cannot replay after claim clears");frame(true,0,0);var released=NativeInputOwnership.read();check(released.allows(0),"newer tracked neutral frame rearms physical side");check(released.generation(0)!=first.generation(0),"neutral rearm does not resurrect queued request lineage");
  VrApi.consumed[1]=true;var consumed=NativeInputOwnership.read();check(consumed.allows(0)&&!consumed.allows(1),"transient right grip consumption preserves left permission");VrApi.consumed[1]=false;frame(true,0,0);check(NativeInputOwnership.read().allows(1),"consumed-side neutral rearm supported");
  frame(true,XrBackend.GRIP,XrBackend.TRIGGER);var raw=Engine.latestInput;PhysicalBandaging.blocked=true;var bandaged=NativeInputOwnership.read();check(bandaged.globalBlocked()&&!bandaged.allows(0)&&!bandaged.allows(1),"claimed bandaging has global native action authority");check(Engine.latestInput==raw&&raw.left().down(XrBackend.GRIP)&&raw.right().down(XrBackend.TRIGGER),"raw pose and buttons are never replaced or synthesized as released");PhysicalBandaging.blocked=false;frame(true,0,0);check(NativeInputOwnership.read().allows(0)&&NativeInputOwnership.read().allows(1),"bandage release requires fresh neutral both hands");
  long queued=NativeInputOwnership.generation(0);VrApi.grabbed[0]=true;NativeInputOwnershipAdvice.exit(null);VrApi.grabbed[0]=false;frame(true,0,0);NativeInputOwnershipAdvice.exit(null);check(NativeInputOwnership.allows(0)&&NativeInputOwnership.generation(0)!=queued,"passive native update catches claim while authored request remains queued");
  var lock=new Object();PhysicalBandaging.forbidden=lock;try(var scope=NativeInputOwnership.open()){int calls=PhysicalBandaging.calls+VrApi.calls;long generation=scope.snapshot().generation(0);synchronized(lock){try(var nested=NativeInputOwnership.open()){check(NativeInputOwnership.allows(0)&&NativeInputOwnership.generation(0)==generation,"nested authored route reuses detached ownership");check(nested.snapshot()==scope.snapshot(),"nested scope preserves exact snapshot identity");}}check(PhysicalBandaging.calls+VrApi.calls==calls,"no native ownership query occurs inside route monitor");}PhysicalBandaging.forbidden=null;
  try(var scope=NativeInputOwnership.open()){int calls=PhysicalBandaging.calls+VrApi.calls;frame(true,0,0);check(!NativeInputOwnership.allows(0),"new raw frame invalidates old scoped permission");check(PhysicalBandaging.calls+VrApi.calls==calls,"stale nested permission fails closed without native refresh");}check(NativeInputOwnership.read().allows(0),"fresh outer read uses current raw frame");
  try(var outer=NativeInputOwnership.open()){try{try(var inner=NativeInputOwnership.open()){throw new IllegalStateException();}}catch(IllegalStateException expected){check(NativeInputOwnership.read()==outer.snapshot(),"failed nested route restores outer snapshot");}}
  var scope=NativeInputOwnership.open();Throwable[] error={null};var thread=new Thread(()->{try{scope.close();}catch(Throwable wrong){error[0]=wrong;}});thread.start();thread.join();check(error[0] instanceof IllegalStateException,"ownership scope cannot move to foreign thread");scope.close();
  PhysicalBandaging.fail=true;check(NativeInputOwnership.read().globalBlocked(),"native API failure fails closed");PhysicalBandaging.fail=false;frame(true,0,0);check(NativeInputOwnership.read().allows(0),"available providers recover only on new neutral frame");var old=NativeInputOwnership.read();NativeInputOwnershipAdvice.exit(new IllegalStateException());check(!old.allows(0)&&!old.allows(1),"failed native update invalidates queued/scoped lineages");frame(true,0,0);check(NativeInputOwnership.read().allows(0),"native update failure recovers with fresh neutral");frame(false,0,0);check(NativeInputOwnership.read().globalBlocked(),"focus loss retains native authority and invalidates permission");frame(true,XrBackend.GRIP,0);check(!NativeInputOwnership.read().allows(0),"focus recovery cannot replay held grip");frame(true,0,0);check(NativeInputOwnership.read().allows(0),"focus recovery rearmed on neutral");
  var pose=Engine.latestInput.head();Engine.latestInput=new XrBackend.Frame(System.nanoTime()-300_000_000L,true,true,pose,List.of(),Engine.latestInput.left(),Engine.latestInput.right());check(NativeInputOwnership.read().globalBlocked(),"stale raw frame remains ineligible despite fresh ownership query");System.out.println("Native input ownership: "+checks+" checks passed; authored providers, raw input intact");
 }
}
